<script setup lang="ts">
import {onMounted,onUnmounted,reactive,ref} from 'vue';import {request,requestPage,waitJob,waitMail,errorText} from '../api';import type {Mail} from '../types';import {displayTime,statusNames,formFromTemporal,reviewTemporal,kindNames} from '../domain';import Icon from '../components/Icon.vue';import Modal from '../components/Modal.vue';
const mails=ref<Mail[]>([]),loading=ref(false),busy=ref(false),error=ref(''),message=ref(''),selected=ref<Mail>(),file=ref<HTMLInputElement>(),filter=ref('all'),cursor=ref<string|null>(),edits=reactive<Record<string,any>>({});
async function load(more=false){loading.value=true;try{const result=await requestPage<Mail>('/emails?limit=200'+(filter.value==='review'?'&state=review_needed':'')+(more&&cursor.value?'&cursor='+encodeURIComponent(cursor.value):''));mails.value=more?[...mails.value,...result.data]:result.data;cursor.value=result.next_cursor;}catch(e){error.value=errorText(e);}finally{loading.value=false;}}
async function importFile(e:Event){const f=(e.target as HTMLInputElement).files?.[0];if(!f)return;error.value='';busy.value=true;try{const body=new FormData();body.append('file',f);const job=await request('/emails/import','POST',body);if(job.job_id){const result=await waitJob(job.job_id);if(result.result?.message_id)await waitMail(result.result.message_id);}message.value='邮件已导入，识别结果已更新。';await load();}catch(e){error.value=errorText(e);}finally{busy.value=false;if(file.value)file.value.value='';}}
async function open(mail:Mail){try{selected.value=await request(`/emails/${mail.id}`);for(const c of selected.value?.candidates??[])edits[c.candidate_id]={selected:true,title:c.title,...formFromTemporal(c.temporal)};}catch(e){error.value=errorText(e);}}
async function review(ignore=false){if(!selected.value)return;busy.value=true;error.value='';try{const m=selected.value;const decisions=(m.candidates??[]).filter(c=>!c.state||c.state==='open').map(c=>{const e=edits[c.candidate_id];return {candidate_id:c.candidate_id,action:ignore||!e.selected?'ignore':'edit',changes:ignore||!e.selected?undefined:{title:e.title,kind:c.kind,priority:c.priority,temporal:reviewTemporal(c.temporal,e,c.kind)}};});if(!decisions.length)decisions.push({candidate_id:'all',action:'ignore',changes:undefined});await request(`/emails/${m.id}/review`,'POST',{expected_version:m.version,decisions});selected.value=undefined;message.value=ignore?'已忽略这封邮件。':'审核结果已保存，已接受的动作可以在待办中查看。';await load();}catch(e){error.value=errorText(e);}finally{busy.value=false;}}
async function reparse(){if(!selected.value)return;busy.value=true;try{const job=await request(`/emails/${selected.value.id}/reparse`,'POST',{expected_version:selected.value.version,mode:'rules'});if(job.job_id)await waitJob(job.job_id);await waitMail(selected.value.id);await open(selected.value);await load();}catch(e){error.value=errorText(e);}finally{busy.value=false;}}
let refreshTimer:ReturnType<typeof setInterval>;
onMounted(()=>{load();refreshTimer=setInterval(()=>{if(!document.hidden&&!selected.value&&!busy.value&&!cursor.value&&!loading.value&&mails.value.length<=200)load();},30000);});
onUnmounted(()=>clearInterval(refreshTimer));
</script>
<template><section class="page"><div class="page-eyebrow"><span class="tiny-line"/>从通知，到行动</div><div class="page-heading"><div><h1>收件识别<span class="accent-dot">。</span></h1><p>重要信息留有依据，不确定的地方由你确认。</p></div><input ref="file" type="file" accept=".eml,message/rfc822" hidden @change="importFile"><button class="button primary" :disabled="busy" @click="file?.click()"><Icon name="upload" :size="18"/>{{busy?'正在处理…':'导入 .eml 邮件'}}</button></div><div class="info-banner"><Icon name="mail" :size="22"/><div><strong>你的邮箱保持原样</strong><p>只读获取邮件，保留必要证据。需要更多信息时，识别结果会进入待确认。</p></div></div><p v-if="error" class="error-box" role="alert">{{error}}</p><p v-if="message" class="success-box" role="status">{{message}}</p><div class="section-toolbar"><div class="tabs"><button :class="{selected:filter==='all'}" @click="filter='all';load()">全部邮件</button><button :class="{selected:filter==='review'}" @click="filter='review';load()">待确认</button></div><button class="text-button" @click="load()">刷新</button></div><div v-if="loading" class="loading-block">正在读取邮件…</div><div v-else-if="!mails.length" class="empty-state"><div class="empty-icon"><Icon name="inbox" :size="36"/></div><h3>让招聘通知，变成清楚的下一步</h3><p>导入一封 .eml 邮件，或在设置中连接 QQ 邮箱。</p></div><button v-for="mail in mails" :key="mail.id" class="mail-row" @click="open(mail)"><span class="mail-icon"><Icon name="mail"/></span><span class="mail-main"><strong>{{mail.subject||'无主题邮件'}}</strong><small>{{mail.from_addr}}</small></span><span class="badge" :class="{warning:mail.state==='review_needed'}">{{statusNames[mail.state]??mail.state}}</span><span class="mail-date">{{displayTime(mail.first_seen_at)}}</span><Icon name="chevron" :size="18"/></button><button v-if="cursor" class="button" :disabled="loading" @click="load(true)">加载更多邮件</button></section><Modal v-if="selected" title="查看与确认邮件" wide @close="selected=undefined"><div class="review-layout"><div class="mail-evidence"><span class="overline">邮件来源</span><h3>{{selected.subject}}</h3><p class="muted">{{selected.from_addr}}</p><pre>{{selected.text_excerpt||'正文缓存不可用，仍可查看已经保留的任务。'}}</pre><div v-if="selected.issues" class="field-help">{{selected.issues}}</div></div><div class="review-actions"><p v-if="JSON.stringify(selected).includes('CHANGE_REQUIRES_REVIEW')" class="error-box">这是改期或取消通知。请先在「今日待办」核对并编辑或取消原事项，再将这封邮件标记为已处理。</p><span class="overline">建议行动 · 请核对时间</span><p class="field-help">每个动作单独确认。只有日期时不会自动生成定时提醒。</p><div v-for="c in selected.candidates?.filter(c=>!c.state||c.state==='open')" :key="c.candidate_id" class="candidate-card"><label class="check-label"><input v-model="edits[c.candidate_id].selected" type="checkbox"/>{{kindNames[c.kind]??c.kind}}</label><label>待办名称<input v-model="edits[c.candidate_id].title"/></label><p class="quote">{{c.temporal.raw_text||'邮件未给出明确时间'}}</p><div class="form-row"><label>日期<input v-model="edits[c.candidate_id].date" type="date"/></label><label>时间<input v-model="edits[c.candidate_id].time" type="time"/></label></div><label>时区<select v-model="edits[c.candidate_id].timezone"><option value="Asia/Shanghai">北京时间</option><option value="Asia/Tokyo">东京时间</option><option value="UTC">UTC</option></select></label><p v-if="c.issues" class="field-help">{{c.issues}}</p></div><p v-if="!selected.candidates?.length" class="subtle-box">这封邮件没有可直接创建的动作。改期或取消请先在待办中处理原事项，再将此邮件标为已处理。</p><p v-if="error" class="error-box">{{error}}</p></div></div><footer class="modal-actions"><button class="text-button" :disabled="busy" @click="reparse">重新识别</button><div class="spacer"/><button class="button" :disabled="busy" @click="review(true)">忽略 / 已处理</button><button v-if="selected.candidates?.some(c=>!c.state||c.state==='open')&&!JSON.stringify(selected).includes('CHANGE_REQUIRES_REVIEW')" class="button primary" :disabled="busy" @click="review()">确认所选行动</button></footer></Modal></template>
